const A={"logo":"data:image/png;base64,","bg":"data:image/jpeg;base64,","mug":"data:image/jpeg;base64,","glass":"data:image/jpeg;base64,","hotbox":"data:image/jpeg;base64,","cook":"data:image/jpeg;base64,","steelo":"data:image/jpeg;base64,","larah":"data:image/jpeg;base64,","viva":"data:image/jpeg;base64,","earbuds":"data:image/jpeg;base64,","speaker":"data:image/jpeg;base64,"};
const SECRET="PLANETG-DASARA-2026-2026";

function tierFor(a){
 if(a<10000)return {tier:"₹5,000–₹9,999",gifts:["Libra Mug + Planet G Key Chain"]};
 if(a<20000)return {tier:"₹10,000–₹19,999",gifts:["6 Glass Set","Hot Box"]};
 if(a<35000)return {tier:"₹20,000–₹34,999",gifts:["Hot Box + Neckband","Red Chef Cook & Serve","Hot Box + Libra Coffee Mug"]};
 if(a<=60000)return {tier:"₹35,000–₹60,000",gifts:["Red Chef Cook & Serve","Signatize Bluetooth Speaker","Neckband"]};
 if(a<100000)return {tier:"₹60,001–₹99,999",gifts:["Red Chef Cook & Serve + 6 Piece Glass Set","Red Chef Hot & Cold – Steelo + Libra Coffee Mug","9 Piece Dinner Set"]};
 return {tier:"₹1,00,000+",gifts:["Red Chef Hot & Cold – Steelo","24 Piece Dinner Set","Red Chef Cook & Serve + Hot Box","Neckband + Hot Box"]};
}
function b64u(s){return btoa(unescape(encodeURIComponent(s))).replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_')}
function from64(s){s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return decodeURIComponent(escape(atob(s)))}
async function hmac(payload){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign']);const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(payload));return b64u(String.fromCharCode(...new Uint8Array(sig)))}
async function makeToken(obj){const p=b64u(JSON.stringify(obj));return p+'.'+await hmac(p)}
async function verifyToken(tok){const [p,s]=String(tok||'').split('.');if(!p||!s||await hmac(p)!==s)throw Error('Invalid session.');return JSON.parse(from64(p))}
async function otpFor(m,t,b){const x=await hmac(m+'|'+t+'|'+b);return String(parseInt(x.slice(0,8),16)%1000000).padStart(6,'0')}

const CSS=`<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Arial,Helvetica,sans-serif;color:#24191b}body{background:linear-gradient(rgba(255,250,248,.88),rgba(255,250,248,.94)),url($data:image/jpeg;base64,) center/cover fixed}header{height:78px;background:linear-gradient(135deg,#8d0711,#e52b38);color:white;display:flex;align-items:center;padding:10px 18px;gap:13px;box-shadow:0 5px 22px #65030a33;position:sticky;top:0;z-index:5}header img{width:57px;height:57px;border-radius:50%;background:white;padding:4px;object-fit:contain}header .brand{font-size:23px;font-weight:900;letter-spacing:.4px}header .sub{font-size:14px;margin-top:3px;opacity:.9}main{max-width:1080px;margin:0 auto;padding:24px 18px 50px}.panel{background:rgba(255,255,255,.96);border-radius:28px;box-shadow:0 18px 55px #6e111c1c;border:1px solid #f0d9d7;padding:28px}h1{margin:0;color:#bd1724;font-size:32px;text-align:center}.lead{text-align:center;font-size:17px;margin:10px 0 22px}label{display:block;font-weight:800;margin:15px 0 7px}input,button{font:inherit}input{width:100%;padding:15px 16px;border:1px solid #dfcacc;border-radius:14px;font-size:17px;outline:none}input:focus{border-color:#d11b2a;box-shadow:0 0 0 3px #d11b2a15}button{border:0;border-radius:15px;padding:16px 18px;width:100%;background:linear-gradient(135deg,#bf101f,#e22535);color:#fff;font-weight:900;font-size:17px;box-shadow:0 8px 20px #a50b1826}button:disabled{opacity:.55}.msg{margin-top:16px;padding:15px;border-radius:14px}.ok{background:#e9f8ee;color:#155a2b}.err{background:#ffe8e8;color:#99101a}.otp{font-size:42px;letter-spacing:10px;text-align:center;color:#bd1724;font-weight:900;margin:12px 0}.tier{font-weight:800;margin-top:10px}
.hero{text-align:center;margin-bottom:22px}.hero h1{font-size:36px}.hero p{font-size:18px;margin:9px 0}.stage{text-align:center;color:#c01827;font-size:20px;font-weight:900;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.gift{position:relative;aspect-ratio:1;border-radius:50%;background:linear-gradient(145deg,#fff,#fff8f6);border:6px solid #c01827;box-shadow:inset 0 0 0 4px #fff,0 10px 28px #6b07142a;overflow:hidden;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:transform .25s,box-shadow .25s}.gift:hover{transform:translateY(-4px);box-shadow:inset 0 0 0 4px #fff,0 15px 32px #6b07143a}.gift .shine{position:absolute;inset:0;background:linear-gradient(120deg,transparent 25%,#ffffff80 43%,transparent 58%);transform:translateX(-130%);animation:shine 3.5s infinite;pointer-events:none}@keyframes shine{to{transform:translateX(130%)}}.gift .photos{position:absolute;inset:12px;display:flex;align-items:center;justify-content:center;gap:4px}.gift .photos img{width:82%;height:80%;object-fit:contain;background:#fff;border-radius:16px;padding:5px;box-shadow:0 5px 14px #00000018;filter:drop-shadow(0 7px 7px #0002)}.gift.duo .photos img{width:48%;height:68%}.gift.trio .photos img{width:31%;height:58%}.gift .label{position:absolute;left:10%;right:10%;bottom:10px;background:linear-gradient(#970814,#c91927);color:white;border-radius:12px;padding:8px 6px;text-align:center;font-weight:900;font-size:12px;line-height:1.15;box-shadow:0 5px 12px #7b061333}.gift.mega{background:linear-gradient(145deg,#fff,#fff8f6);border-color:#c01827}.mega .photos{display:grid;grid-template-columns:repeat(3,1fr);padding:18px;gap:7px}.mega .photos img{width:100%;height:100%;object-fit:contain;background:#fff;border-radius:10px;padding:5px;box-shadow:0 3px 8px #00000012}.mega .label{background:linear-gradient(#8d0711,#c69211)}.closed{background:radial-gradient(circle at 35% 28%,#f0444f,#9a0613 70%);border-color:#c01827;box-shadow:0 14px 35px #65020e55;cursor:pointer}.closed::before{content:'G';font-size:68px;font-weight:900;color:#fff;text-shadow:0 4px 12px #570008}.closed .photos,.closed .label,.closed .shine{display:none}.shuffle .gift{animation:shake .18s infinite alternate}@keyframes shake{from{transform:translateY(-7px) rotate(-2deg)}to{transform:translateY(7px) rotate(2deg)}}.chooseHint{text-align:center;color:#8e0a15;font-weight:800;margin:18px 0}.winner{max-width:800px;margin:28px auto;background:linear-gradient(180deg,#fff,#fff9ef);border:4px solid #d9ae2f;border-radius:30px;padding:32px 22px;text-align:center;box-shadow:0 20px 55px #5c111d22;animation:pop .6s ease}@keyframes pop{0%{transform:scale(.75);opacity:0}100%{transform:scale(1);opacity:1}}.winner .confetti{font-size:42px}.winner h2{font-size:27px;color:#bd1724;margin:8px 0}.winner .prize{font-size:38px;font-weight:900;color:#bc1623;margin:18px 0}.winner img{max-width:270px;max-height:220px;object-fit:contain;filter:drop-shadow(0 12px 16px #0002)}.winner .note{font-size:18px;color:#8f1720}.hidden{display:none!important}.small{font-size:13px;color:#7d5a5e}@media(max-width:650px){main{padding:15px 10px 40px}.panel{padding:18px 12px;border-radius:22px}h1,.hero h1{font-size:27px}.grid{gap:10px}.gift{border-width:5px}.gift .label{font-size:9px;bottom:7px;padding:6px 4px}.gift.duo .photos img{width:48%;height:61%}.gift.trio .photos img{height:53%}.closed::before{font-size:48px}.winner .prize{font-size:27px}}
</style>`;

function header(sub){return `<header><img src="${A.logo}"><div><div class="brand">PLANET G</div><div class="sub">${sub}</div></div></header>`}

const STAFF_HTML=()=>`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planet G Staff Portal</title>${CSS}</head><body>${header('Staff Portal • Dasara 2026')}<main><section class="panel"><h1>Generate Customer OTP</h1><p class="lead">Enter the bill details. <b>Do not show the bill value or tier to the customer.</b></p><form id="f"><label>Customer Name</label><input id="name" required placeholder="Customer name"><label>Mobile Number</label><input id="mobile" inputmode="numeric" maxlength="10" required placeholder="10-digit mobile number"><label>Bill Number</label><input id="bill" required placeholder="Bill number"><label>Bill Value (₹)</label><input id="value" inputmode="decimal" required placeholder="e.g. 27500"><button>GENERATE CUSTOMER OTP</button></form><div id="out"></div></section></main><script>
const f=document.getElementById('f'),out=document.getElementById('out');
f.addEventListener('submit',async e=>{e.preventDefault();out.innerHTML='<div class="msg">Generating…</div>';try{const r=await fetch('/api/staff/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({customerName:document.getElementById('name').value.trim(),mobile:document.getElementById('mobile').value.trim(),billNumber:document.getElementById('bill').value.trim(),billValue:document.getElementById('value').value.trim()})});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to generate OTP');out.innerHTML='<div class="msg ok"><div>Customer OTP</div><div class="otp">'+d.otp+'</div><b>Give this OTP to the customer.</b><p>Customer must enter the same mobile number + this OTP.</p><div class="tier">Eligible tier: '+d.tier+'</div></div>'}catch(x){out.innerHTML='<div class="msg err">'+x.message+'</div>'}});
</script></body></html>`;

const CUSTOMER_HTML=()=>`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planet G Dasara Gift Game</title>${CSS}</head><body>${header('Dasara 2026 Gift Game')}<main><section class="panel" id="login"><div class="hero"><h1>🎉 Your Dasara Surprise Awaits! 🎉</h1><p>Every Planet G customer deserves a little surprise.</p></div><label>Mobile Number</label><input id="cm" inputmode="numeric" maxlength="10" placeholder="10-digit mobile number"><label>OTP</label><input id="co" inputmode="numeric" maxlength="6" placeholder="6-digit OTP"><button id="unlock">UNLOCK MY GIFT GAME</button><div id="loginMsg"></div></section><section id="game" class="hidden"><div class="hero"><h1>🎊 Your Dasara Surprise Awaits! 🎊</h1><p>Every Planet G customer deserves a little surprise.</p></div><div id="stage" class="stage">First, take a look at all 9 gifts…</div><div id="grid" class="grid"></div><button id="start">CLOSE CARDS &amp; START SHUFFLE</button><div id="hint" class="chooseHint hidden">Cards are shuffled! Choose any one card. 🎁</div><div id="result"></div></section></main><script>
const A=${JSON.stringify(A)};
const cm=document.getElementById('cm'),co=document.getElementById('co'),unlock=document.getElementById('unlock'),login=document.getElementById('login'),game=document.getElementById('game'),grid=document.getElementById('grid'),start=document.getElementById('start'),stage=document.getElementById('stage'),hint=document.getElementById('hint'),result=document.getElementById('result');
let token='',musicTimer=null,audioCtx=null;
const showcases=[
 {name:'Libra Mug + Key Chain',imgs:['mug'],cls:''},
 {name:'6 Glass Set',imgs:['glass'],cls:''},
 {name:'Hot Box',imgs:['hotbox'],cls:''},
 {name:'Hot Box + Neckband',imgs:['hotbox','earbuds'],cls:'duo'},
 {name:'Red Chef Cook & Serve',imgs:['cook'],cls:''},
 {name:'Hot Box + Libra Mug',imgs:['hotbox','mug'],cls:'duo'},
 {name:'Signatize Bluetooth Speaker',imgs:['speaker'],cls:''},
 {name:'9 Piece Dinner Set',imgs:['larah'],cls:''},
 {name:'MEGA GIFT COMBO',imgs:['mug','glass','hotbox','cook','speaker','larah'],cls:'mega'}
];
const prizeImages={
 'Libra Mug + Planet G Key Chain':['mug'],
 '6 Glass Set':['glass'],
 'Hot Box':['hotbox'],
 'Hot Box + Neckband':['hotbox','earbuds'],
 'Red Chef Cook & Serve':['cook'],
 'Hot Box + Libra Coffee Mug':['hotbox','mug'],
 'Signatize Bluetooth Speaker':['speaker'],
 'Neckband':['earbuds'],
 'Red Chef Cook & Serve + 6 Piece Glass Set':['cook','glass'],
 'Red Chef Hot & Cold – Steelo + Libra Coffee Mug':['steelo','mug'],
 '9 Piece Dinner Set':['larah'],
 'Red Chef Hot & Cold – Steelo':['steelo'],
 '24 Piece Dinner Set':['viva'],
 'Red Chef Cook & Serve + Hot Box':['cook','hotbox'],
 'Neckband + Hot Box':['earbuds','hotbox']
};
function renderShowcases(closed=false){grid.innerHTML='';showcases.forEach((g,i)=>{const d=document.createElement('div');d.className='gift '+(closed?'closed ':'')+(g.cls||'');d.dataset.i=i;if(!closed){d.innerHTML='<div class="shine"></div><div class="photos">'+g.imgs.map(x=>'<img src="'+A[x]+'">').join('')+'</div><div class="label">'+g.name+'</div>'}grid.appendChild(d)})}
function playTone(freq,dur,type='sine',vol=.035){if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}
function startMusic(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();const notes=[261.63,329.63,392,493.88,392,329.63];let n=0;musicTimer=setInterval(()=>{playTone(notes[n++%notes.length],1.6,'sine',.018)},1200);playTone(261.63,1.5,'sine',.018)}
function shuffleSound(){for(let i=0;i<10;i++)setTimeout(()=>playTone(150+Math.random()*500,.12,'triangle',.045),i*90)}
function congratsVoice(prize){try{const u=new SpeechSynthesisUtterance('Congratulations! You have won '+prize+'. Thank you for choosing Planet G.');u.rate=.9;u.pitch=1.05;u.volume=1;speechSynthesis.cancel();speechSynthesis.speak(u)}catch(e){}}
function resultImage(prize){return (prizeImages[prize]||['mug']).map(x=>'<img src="'+A[x]+'">').join('')}

unlock.addEventListener('click',async()=>{loginMsg.innerHTML='';try{const r=await fetch('/api/customer/verify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mobile:cm.value,otp:co.value})});const d=await r.json();if(!r.ok)throw Error(d.error||'Invalid OTP');token=d.token;login.classList.add('hidden');game.classList.remove('hidden');renderShowcases(false);}catch(e){loginMsg.innerHTML='<div class="msg err">'+e.message+'</div>'}});
start.addEventListener('click',async()=>{start.disabled=true;startMusic();shuffleSound();stage.textContent='✨ Shuffling your Dasara surprise…';grid.classList.add('shuffle');await new Promise(r=>setTimeout(r,3500));grid.classList.remove('shuffle');renderShowcases(true);stage.textContent='🎁 Your cards are ready!';hint.classList.remove('hidden');grid.querySelectorAll('.gift').forEach(card=>card.addEventListener('click',()=>choose(card)));start.classList.add('hidden')});
async function choose(card){if(card.dataset.done)return;grid.querySelectorAll('.gift').forEach(x=>x.dataset.done='1');hint.classList.add('hidden');stage.textContent='Opening your surprise…';playTone(523.25,.25,'sine',.06);try{const r=await fetch('/api/customer/claim',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to reveal gift');result.innerHTML='<div class="winner"><div class="confetti">🎉🎊🎉</div><div>CONGRATULATIONS!</div><h2>YOU WON!</h2><div class="prize">'+d.prize+'</div><div>'+resultImage(d.prize)+'</div><p class="note">Please collect your gift from our Planet G team.</p><p>Thank You For Your Trust ❤️</p></div>';stage.classList.add('hidden');congratsVoice(d.prize);if(musicTimer){clearInterval(musicTimer);musicTimer=null}}catch(e){result.innerHTML='<div class="msg err">'+e.message+'</div>'}}
renderShowcases(false);
</script></section></main></body></html>`;

export default {async fetch(request){const u=new URL(request.url);
 if(request.method==='GET'&&(u.pathname==='/'||u.pathname==='/customer'||u.pathname==='/play'))return new Response(CUSTOMER_HTML(),{headers:{'content-type':'text/html;charset=UTF-8','cache-control':'no-store'}});
 if(request.method==='GET'&&(u.pathname==='/staff'||u.pathname==='/staff.html'))return new Response(STAFF_HTML(),{headers:{'content-type':'text/html;charset=UTF-8','cache-control':'no-store'}});
 if(u.pathname==='/api/health')return Response.json({ok:true,service:'Planet G Dasara Gift Game'});
 if(request.method!=='POST')return new Response('Not found',{status:404});
 if(u.pathname==='/api/staff/session'){try{const b=await request.json(),m=String(b.mobile||'').replace(/\D/g,''),a=Number(b.billValue);if(!b.customerName||m.length!==10||!b.billNumber||!Number.isFinite(a)||a<5000)throw Error('Enter valid details and a bill value of at least ₹5,000.');const t=tierFor(a),bucket=Math.floor(Date.now()/600000),otp=await otpFor(m,t.tier,bucket),token=await makeToken({mobile:m,tier:t.tier,gifts:t.gifts,bucket,exp:Date.now()+600000});return Response.json({ok:true,otp,tier:t.tier,token})}catch(e){return Response.json({error:e.message||'Unable to generate OTP'},{status:400})}}
 if(u.pathname==='/api/customer/verify'){try{const b=await request.json(),m=String(b.mobile||'').replace(/\D/g,''),o=String(b.otp||'');if(m.length!==10||o.length!==6)throw Error('Invalid mobile number or OTP.');const now=Math.floor(Date.now()/600000);let match=null;for(const t of [tierFor(5000),tierFor(10000),tierFor(20000),tierFor(35000),tierFor(60001),tierFor(100000)])for(const buck of [now,now-1])if(await otpFor(m,t.tier,buck)===o)match={mobile:m,tier:t.tier,gifts:t.gifts,bucket:buck,exp:Date.now()+300000};if(!match)throw Error('Incorrect or expired OTP.');return Response.json({ok:true,token:await makeToken(match)})}catch(e){return Response.json({error:e.message||'Verification failed'},{status:401})}}
 if(u.pathname==='/api/customer/claim'){try{const s=await verifyToken((await request.json()).token);if(s.exp<Date.now())throw Error('Session expired. Please ask staff for a new OTP.');const prize=s.gifts[Math.floor(Math.random()*s.gifts.length)];return Response.json({ok:true,prize})}catch(e){return Response.json({error:e.message||'Unable to reveal gift'},{status:400})}}
 return new Response('Not found',{status:404});
}};
